import java.util.*; public class TopKFrequentElements { public int[] topKFrequent(int[] nums, int k) { Map<Integer, Integer> countMap = new HashMap<>(); for (int num : nums) { countMap.put(num, countMap.getOrDefault(num, 0) + 1); } PriorityQueue<Map.Entry<Integer, Integer>> minHeap = new PriorityQueue<>(Comparator.comparingInt(Map.Entry::getValue)); for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) { minHeap.offer(entry); if (minHeap.size() > k) { minHeap.poll(); } } int[] result = new int[k]; int i = 0; while (!minHeap.isEmpty()) { result[i++] = minHeap.poll().getKey(); } return result; } }
